// Local Phone Manager Component for new students
  const PhoneManagerLocal = ({ form, setForm }: { form: typeof emptyForm; setForm: React.Dispatch<React.SetStateAction<typeof emptyForm>> }) => {
    const phones = form.phones || [];
    const phoneInputRef = useRef<HTMLInputElement>(null);

    const addPhone = () => {
      const newPhone = {
        phone_number: phoneInputRef.current?.value || "",
        country_code: form.phones_temp_country || "+20",
        is_personal: form.phones_temp_personal ?? true,
        is_parent: form.phones_temp_parent ?? false,
        is_whatsapp: form.phones_temp_whatsapp ?? false,
        is_call: form.phones_temp_call ?? true,
        is_primary: form.phones_temp_primary ?? false,
        parent_name: form.phones_temp_parent_name || "",
        parent_relationship: form.phones_temp_parent_relationship || "",
      };
      if (!newPhone.phone_number) { alert("يرجى إدخال الرقم"); return; }
      setForm({ ...form, phones: [...phones, newPhone] });
      // Reset temp fields
      setForm({
        ...form,
        phones_temp_country: "+20",
        phones_temp_personal: true,
        phones_temp_parent: false,
        phones_temp_whatsapp: false,
        phones_temp_call: true,
        phones_temp_primary: false,
        phones_temp_parent_name: "",
        phones_temp_parent_relationship: "",
      });
      phoneInputRef.current?.focus();
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === "Enter") {
        e.preventDefault();
        addPhone();
      }
    };

    const handleBlur = () => {
      // Auto-add on blur if there's a value
      if (phoneInputRef.current?.value?.trim()) {
        addPhone();
      }
    };

    return (
      <div className="space-y-3">
        {/* Add/Edit Phone Form */}
        <div className="rounded-lg bg-slate-50 p-4 space-y-3">
          <h5 className="font-medium text-slate-700 flex items-center gap-2">
            إضافة رقم جديد
            <span className="text-xs text-slate-400">(اضغط Enter أو اخرج من الحقل للإضافة التلقائية)</span>
          </h5>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="mb-1 block text-xs text-slate-500">الرقم *</label>
              <input
                type="tel"
                placeholder="01xxxxxxxxx"
                ref={phoneInputRef}
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm dir-ltr"
                required
                dir="ltr"
                onKeyDown={handleKeyDown}
                onBlur={handleBlur}
              />
            </div>
            <div>
              <label className="mb-1 block text-xs text-slate-500">الدولة</label>
              <select
                value={form.phones_temp_country || "+20"}
                onChange={(e) => setForm({ ...form, phones_temp_country: e.target.value })}
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
              >
                {COUNTRIES.map((c) => <option key={c.code} value={c.code}>{c.flag} {c.name} ({c.code})</option>)}
              </select>
            </div>
          </div>
          <div className="flex flex-wrap gap-3">
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_personal ?? true} onChange={(e) => setForm({ ...form, phones_temp_personal: e.target.checked })} className="rounded" />
              شخصي
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_whatsapp ?? false} onChange={(e) => setForm({ ...form, phones_temp_whatsapp: e.target.checked })} className="rounded" />
              واتساب 💬
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_call ?? true} onChange={(e) => setForm({ ...form, phones_temp_call: e.target.checked })} className="rounded" />
              تواصل 📞
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_parent ?? false} onChange={(e) => setForm({ ...form, phones_temp_parent: e.target.checked })} className="rounded" />
              ولي أمر 👨‍👩‍👧
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_primary ?? false} onChange={(e) => setForm({ ...form, phones_temp_primary: e.target.checked })} className="rounded" />
              أساسي ⭐
            </label>
          </div>
          {form.phones_temp_parent && (
            <div className="grid grid-cols-2 gap-3 pt-2 border-t border-slate-200">
              <input
                placeholder="اسم ولي الأمر"
                value={form.phones_temp_parent_name || ""}
                onChange={(e) => setForm({ ...form, phones_temp_parent_name: e.target.value })}
                className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
              />
              <select
                value={form.phones_temp_parent_relationship || ""}
                onChange={(e) => setForm({ ...form, phones_temp_parent_relationship: e.target.value })}
                className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
              >
                <option value="">صلة القرابة</option>
                <option value="father">أب</option>
                <option value="mother">أم</option>
                <option value="guardian">وصي</option>
                <option value="other">أخرى</option>
              </select>
            </div>
          )}
          <button
            type="button"
            onClick={addPhone}
            className="w-full rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
          >
            ➕ إضافة الرقم
          </button>
        </div>

