public function index(Request $request)
    {
        $query = Student::query()
            ->with(['branch', 'user', 'parents', 'phones'])
            ->when($request->filled('status'), fn ($q) => $q->where('status', $request->string('status')))
            ->when($request->filled('branch_id'), fn ($q) => $q->where('branch_id', $request->string('branch_id')))
            ->when($request->filled('search'), function ($q) use ($request) {
                $search = $request->string('search');
                $q->where(function ($sq) use ($search) {
                    $sq->where('first_name', 'like', "%{$search}%")
                        ->orWhere('last_name', 'like', "%{$search}%")
                        ->orWhere('student_code', 'like', "%{$search}%")
                        ->orWhere('email', 'like', "%{$search}%");
                });
            });

        $students = $query->orderBy('created_at', 'desc')->paginate(50);

        // Add lessons_count, next_lesson, parent info, and phones to each student
        $students->getCollection()->transform(function ($student) {
            $lessonsCount = \App\Models\Lesson::where('student_id', $student->id)->count();
            $nextLesson = \App\Models\Lesson::where('student_id', $student->id)
                ->where('scheduled_start_at', '>', now())
                ->orderBy('scheduled_start_at')
                ->first();

            $student->lessons_count = $lessonsCount;
            $student->next_lesson_date = $nextLesson ? $nextLesson->scheduled_start_at : null;

            // Get parent info
            $parent = \App\Models\ParentModel::whereHas('students', function ($q) use ($student) {
                $q->where('students.id', $student->id);
            })->first();

            $student->parent_name = $parent?->name ?? null;
            $student->parent_phone = $parent?->phone ?? null;

            // Phones are already loaded via relationship
            $student->primary_phone = $student->phones->where('is_primary', true)->first() ?? $student->phones->first();

            return $student;
        });

        return response()->json($students);
    }

