            $student->parent_phone = $primaryParent?->phone ?? null;

            // Phones are already loaded via relationship
            $student->primary_phone = $student->phones
                ->where('is_primary', true)
                ->first() ?? $student->phones->first();

            return $student;
        });

        return response()->json($students);
    }

