107:     public function formatForCountry(string $countryCode = '+20'): string
108:     {
109:         $number = preg_replace('/[^0-9]/', '', $this->phone_number);
110:         
111:         return match ($countryCode) {
112:             '+20' => $this->formatEgypt($number),
113:             '+966' => $this->formatSaudi($number),
114:             '+971' => $this->formatUAE($number),
115:             '+965' => $this->formatKuwait($number),
116:             '+974' => $this->formatQatar($number),
117:             default => $this->phone_number,
118:         };
119:     }
