121:     private function formatEgypt(string $number): string
122:     {
123:         // Egypt: 01xxxxxxxxx (11 digits)
124:         if (str_starts_with($number, '20')) $number = substr($number, 2);
125:         if (str_starts_with($number, '0')) $number = substr($number, 1);
126:         if (strlen($number) === 10 && str_starts_with($number, '1')) {
127:             return '+20 ' . substr($number, 0, 3) . ' ' . substr($number, 3, 3) . ' ' . substr($number, 6);
128:         }
129:         return $this->phone_number;
130:     }
