137:         if (strlen($number) === 9 && str_starts_with($number, '5')) {
138:             return '+966 ' . substr($number, 0, 3) . ' ' . substr($number, 3, 3) . ' ' . substr($number, 6);
139:         }
140:         return $this->phone_number;
