    const phoneInputRef = useRef<HTMLInputElement>(null);
    const [localPhoneValue, setLocalPhoneValue] = useState("");

    const validatePhone = (number: string, countryCode: string): boolean => {
      const cleaned = number.replace(/[\s\-\(\)]/g, '');

      if (!/^\d+$/.test(cleaned)) {
        alert("الرقم يجب أن يحتوي على أرقام فقط");
        return false;
      }

      const lengths: Record<string, { min: number; max: number }> = {
        '+20': { min: 10, max: 11 },
        '+966': { min: 9, max: 10 },
        '+971': { min: 9, max: 10 },
        '+965': { min: 8, max: 8 },
        '+974': { min: 8, max: 8 },
        '+962': { min: 9, max: 10 },
        '+212': { min: 9, max: 10 },
        '+216': { min: 8, max: 8 },
        '+249': { min: 9, max: 10 },
      };

      const rule = lengths[countryCode] ?? { min: 7, max: 15 };
      if (cleaned.length < rule.min || cleaned.length > rule.max) {
        alert(`الرقم يجب أن يكون بين ${rule.min} و ${rule.max} رقماً لهذه الدولة`);
        return false;
      }

      return true;
    };

    const addPhone = () => {
      const number = localPhoneValue.trim();
      if (!number) { alert("يرجى إدخال الرقم"); return; }

      if (!validatePhone(number, form.phones_temp_country || "+20")) return;

      const newPhone = {
        phone_number: number,
        country_code: form.phones_temp_country || "+20",
        is_personal: form.phones_temp_personal ?? true,
        is_parent: form.phones_temp_parent ?? false,
        is_whatsapp: form.phones_temp_whatsapp ?? false,
        is_call: form.phones_temp_call ?? true,
        is_primary: form.phones_temp_primary ?? false,
        parent_name: form.phones_temp_parent_name || "",
        parent_relationship: form.phones_temp_parent_relationship || "",
      };

      setForm(prev => ({ 
        ...prev, 
        phones: [...prev.phones, newPhone],
        phones_temp_country: "+20",
        phones_temp_personal: true,
        phones_temp_parent: false,
        phones_temp_whatsapp: false,
        phones_temp_call: true,
        phones_temp_primary: false,
        phones_temp_parent_name: "",
        phones_temp_parent_relationship: "",
      }));

      setLocalPhoneValue("");
      setTimeout(() => phoneInputRef.current?.focus(), 0);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === "Enter") {
        e.preventDefault();
        addPhone();
      }
    };

    return (
      <div className="space-y-3">
        <div className="rounded-lg bg-slate-50 p-4 space-y-3">
          <h5 className="font-medium text-slate-700 flex items-center gap-2">
            إضافة رقم جديد
            <span className="text-xs text-slate-400">(اضغط Enter للإضافة)</span>
          </h5>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="mb-1 block text-xs text-slate-500">الرقم *</label>
              <input
                type="tel"
                placeholder="01xxxxxxxxx"
                ref={phoneInputRef}
                value={localPhoneValue}
                onChange={(e) => setLocalPhoneValue(e.target.value)}
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm dir-ltr"
                dir="ltr"
                onKeyDown={handleKeyDown}
              />
            </div>
            <div>
              <label className="mb-1 block text-xs text-slate-500">الدولة</label>
              <select
                value={form.phones_temp_country || "+20"}
                onChange={(e) => setForm(prev => ({ ...prev, phones_temp_country: e.target.value }))}
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
              >
                {COUNTRIES.map((c) => <option key={c.code} value={c.code}>{c.flag} {c.name} ({c.code})</option>)}
              </select>
            </div>
          </div>
          <div className="flex flex-wrap gap-3">
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_personal ?? true} onChange={(e) => setForm(prev => ({ ...prev, phones_temp_personal: e.target.checked }))} className="rounded" />
              شخصي
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_whatsapp ?? false} onChange={(e) => setForm(prev => ({ ...prev, phones_temp_whatsapp: e.target.checked }))} className="rounded" />
              واتساب 💬
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_call ?? true} onChange={(e) => setForm(prev => ({ ...prev, phones_temp_call: e.target.checked }))} className="rounded" />
              تواصل 📞
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_parent ?? false} onChange={(e) => setForm(prev => ({ ...prev, phones_temp_parent: e.target.checked }))} className="rounded" />
              ولي أمر 👨‍👩‍👧
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_primary ?? false} onChange={(e) => setForm(prev => ({ ...prev, phones_temp_primary: e.target.checked }))} className="rounded" />
              أساسي ⭐
            </label>
          </div>
          {form.phones_temp_parent && (
            <div className="grid grid-cols-2 gap-3 pt-2 border-t border-slate-200">
              <input
                placeholder="اسم ولي الأمر"
                value={form.phones_temp_parent_name || ""}
                onChange={(e) => setForm(prev => ({ ...prev, phones_temp_parent_name: e.target.value }))}
                className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
              />
              <select
                value={form.phones_temp_parent_relationship || ""}
                onChange={(e) => setForm(prev => ({ ...prev, phones_temp_parent_relationship: e.target.value }))}
                className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
              >
                <option value="">صلة القرابة</option>
                <option value="father">أب</option>
                <option value="mother">أم</option>
                <option value="guardian">وصي</option>
                <option value="other">أخرى</option>
              </select>
            </div>
          )}
          <div className="flex gap-2">
            <button
              type="button"
              onClick={addPhone}
              className="flex-1 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
            >
              ➕ إضافة الرقم
            </button>
            {form.phones.length > 0 && (
              <button
                type="button"
                onClick={() => setForm(prev => ({ ...prev, phones: [] }))}
                className="rounded-lg bg-red-50 px-4 py-2 text-sm font-medium text-red-600 hover:bg-red-100"
              >
                🗑 مسح الكل
              </button>
            )}
          </div>
        </div>

        {phones.length > 0 && (
          <div className="rounded-xl border border-slate-200">
            <h5 className="px-4 py-3 border-b border-slate-200 font-medium text-slate-800">أرقام الهاتف ({phones.length})</h5>
            <ul className="divide-y divide-slate-100">
              {phones.map((phone, idx) => (
                <li key={`phone-${idx}`} className="p-4 hover:bg-slate-50">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <span className="font-mono text-lg font-medium text-slate-800" dir="ltr">{phone.phone_number}</span>
                      <div className="flex gap-1.5">
                        {phone.is_personal && <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs bg-blue-50 text-blue-700">👤 شخصي</span>}
                        {phone.is_whatsapp && <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs bg-green-50 text-green-700">💬 واتساب</span>}
                        {phone.is_call && <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs bg-blue-100 text-blue-700">📞 تواصل</span>}
                        {phone.is_parent && <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs bg-purple-50 text-purple-700">👨‍👩‍👧 ولي أمر</span>}
                        {phone.is_primary && <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs bg-amber-50 text-amber-700">⭐ أساسي</span>}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {phone.is_parent && phone.parent_name && (
                        <span className="text-xs text-purple-600">{phone.parent_name} ({phone.parent_relationship})</span>
                      )}
                      <button onClick={() => setForm(prev => ({ ...prev, phones: prev.phones.filter((_, i) => i !== idx) }))} className="rounded bg-red-50 px-2 py-1 text-xs text-red-600 hover:bg-red-100" title="حذف">🗑</button>
                    </div>
                  </div>
                  {phone.is_parent && phone.parent_name && (
                    <p className="mt-1 text-xs text-purple-600">{phone.parent_name} ({phone.parent_relationship})</p>
                  )}
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    );
  };

