// Local Phone Manager Component for new students
const PhoneManagerLocal = memo(({ form, setForm }: { form: any; setForm: React.Dispatch<React.SetStateAction<any>> }) => {
    const phones = form.phones || [];
    const phoneInputRef = useRef<HTMLInputElement>(null);
    const parentNameInputRef = useRef<HTMLInputElement>(null);
    const parentRelationshipSelectRef = useRef<HTMLSelectElement>(null);

    // Use refs for temporary values to avoid re-renders
    const localPhoneValueRef = useRef("");
    const localParentNameRef = useRef("");
    const localParentRelationshipRef = useRef("");

    const validatePhone = (number: string, countryCode: string): boolean => {
      const cleaned = number.replace(/[\s\-\(\)]/g, '');

      if (!/^\d+$/.test(cleaned)) {
        alert("الرقم يجب أن يحتوي على أرقام فقط");
        return false;
      }

      const lengths: Record<string, { min: number; max: number }> = {
        '+20': { min: 10, max: 11 },
        '+966': { min: 9, max: 10 },
        '+971': { min: 9, max: 10 },
        '+965': { min: 8, max: 8 },
        '+974': { min: 8, max: 8 },
        '+962': { min: 9, max: 10 },
        '+212': { min: 9, max: 10 },
        '+216': { min: 8, max: 8 },
        '+249': { min: 9, max: 10 },
      };

      const rule = lengths[countryCode] ?? { min: 7, max: 15 };
      if (cleaned.length < rule.min || cleaned.length > rule.max) {
        alert(`الرقم يجب أن يكون بين ${rule.min} و ${rule.max} رقماً لهذه الدولة`);
        return false;
      }

      return true;
    };

    const addPhone = () => {
      const number = localPhoneValueRef.current.trim();
      if (!number) { alert("يرجى إدخال الرقم"); return; }

      if (!validatePhone(number, form.phones_temp_country || "+20")) return;

      const newPhone = {
        phone_number: number,
        country_code: form.phones_temp_country || "+20",
        is_personal: form.phones_temp_personal ?? true,
        is_parent: form.phones_temp_parent ?? false,
        is_whatsapp: form.phones_temp_whatsapp ?? false,
        is_call: form.phones_temp_call ?? true,
        is_primary: form.phones_temp_primary ?? false,
        parent_name: localParentNameRef.current || "",
        parent_relationship: localParentRelationshipRef.current || "",
      };

      setForm((prev: any) => ({ 
        ...prev, 
        phones: [...prev.phones, newPhone],
        phones_temp_country: "+20",
        phones_temp_personal: true,
        phones_temp_parent: false,
        phones_temp_whatsapp: false,
        phones_temp_call: true,
        phones_temp_primary: false,
        phones_temp_parent_name: "",
        phones_temp_parent_relationship: "",
      }));

      // Clear refs
      localPhoneValueRef.current = "";
      localParentNameRef.current = "";
      localParentRelationshipRef.current = "";

      // Clear input values directly
      if (phoneInputRef.current) phoneInputRef.current.value = "";
      if (parentNameInputRef.current) parentNameInputRef.current.value = "";
      if (parentRelationshipSelectRef.current) parentRelationshipSelectRef.current.value = "";

      setTimeout(() => phoneInputRef.current?.focus(), 0);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === "Enter") {
        e.preventDefault();
        addPhone();
      }
    };

    const handleParentNameKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === "Enter") {
        e.preventDefault();
        addPhone();
      }
    };

    return (
      <div className="space-y-3">
        <div className="rounded-lg bg-slate-50 p-4 space-y-3">
          <h5 className="font-medium text-slate-700 flex items-center gap-2">
            إضافة رقم جديد
            <span className="text-xs text-slate-400">(اضغط Enter للإضافة)</span>
          </h5>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="mb-1 block text-xs text-slate-500">الرقم *</label>
              <input
                type="tel"
                placeholder="01xxxxxxxxx"
                ref={phoneInputRef}
                onChange={(e) => { localPhoneValueRef.current = e.target.value; }}
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm dir-ltr"
                dir="ltr"
                onKeyDown={handleKeyDown}
              />
            </div>
            <div>
              <label className="mb-1 block text-xs text-slate-500">الدولة</label>
              <select
                ref={parentRelationshipSelectRef}
                value={form.phones_temp_country || "+20"}
                onChange={(e) => { 
                  localParentRelationshipRef.current = e.target.value;
                  setForm((prev: any) => ({ ...prev, phones_temp_country: e.target.value }));
                }}
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
              >
                {COUNTRIES.map((c) => <option key={c.code} value={c.code}>{c.flag} {c.name} ({c.code})</option>)}
              </select>
            </div>
          </div>
          <div className="flex flex-wrap gap-3">
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_personal ?? true} onChange={(e) => setForm((prev: any) => ({ ...prev, phones_temp_personal: e.target.checked }))} className="rounded" />
              شخصي
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_whatsapp ?? false} onChange={(e) => setForm((prev: any) => ({ ...prev, phones_temp_whatsapp: e.target.checked }))} className="rounded" />
              واتساب 💬
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_call ?? true} onChange={(e) => setForm((prev: any) => ({ ...prev, phones_temp_call: e.target.checked }))} className="rounded" />
              تواصل 📞
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_parent ?? false} onChange={(e) => setForm((prev: any) => ({ ...prev, phones_temp_parent: e.target.checked }))} className="rounded" />
              ولي أمر 👨‍👩‍👧
            </label>
            <label className="flex items-center gap-1.5 text-sm text-slate-600 cursor-pointer">
              <input type="checkbox" checked={form.phones_temp_primary ?? false} onChange={(e) => setForm((prev: any) => ({ ...prev, phones_temp_primary: e.target.checked }))} className="rounded" />
              أساسي ⭐
            </label>
          </div>
          {form.phones_temp_parent && (
            <div className="grid grid-cols-2 gap-3 pt-2 border-t border-slate-200">
              <div>
                <label className="mb-1 block text-xs text-slate-500">اسم ولي الأمر</label>
                <input
                  placeholder="اسم ولي الأمر"
                  ref={parentNameInputRef}
                  onChange={(e) => { localParentNameRef.current = e.target.value; }}
                  className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                  onKeyDown={handleParentNameKeyDown}
                />
              </div>
              <div>
                <label className="mb-1 block text-xs text-slate-500">صلة القرابة</label>
                <select
                  value={form.phones_temp_parent_relationship || ""}
                  onChange={(e) => { 
                    localParentRelationshipRef.current = e.target.value;
                    setForm((prev: any) => ({ ...prev, phones_temp_parent_relationship: e.target.value }));
                  }}
                  className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                >
                  <option value="">صلة القرابة</option>
                  <option value="father">أب</option>
                  <option value="mother">أم</option>
                  <option value="guardian">وصي</option>
                  <option value="other">أخرى</option>
                </select>
              </div>
            </div>
          )}
          <div className="flex gap-2">
            <button
              type="button"
              onClick={addPhone}
              className="flex-1 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
            >
              ➕ إضافة الرقم
