"use client";

import { useEffect, useState, useMemo, useCallback } from "react";
import { useRouter } from "next/navigation";
import {
  getTeachers, createTeacher, updateTeacher, deleteTeacher,
  getPrograms, getTeacherRatings, rateTeacher,
  type Teacher, type TeacherRating, type Program,
} from "@/lib/api";

const STATUS_LABEL: Record<Teacher["status"], string> = {
  active: "نشط",
  inactive: "غير نشط",
};

const STATUS_COLORS: Record<Teacher["status"], string> = {
  active: "bg-green-100 text-green-700",
  inactive: "bg-red-100 text-red-700",
};

const CONTRACT_LABEL: Record<string, string> = {
  monthly: "شهري",
  per_lesson: "لكل حصة",
  custom: "مخصص",
};

export default function TeachersPage() {
  const router = useRouter();
  const [teachers, setTeachers] = useState<Teacher[]>([]);
  const [programs, setPrograms] = useState<Program[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterStatus, setFilterStatus] = useState("");
  const [filterProgram, setFilterProgram] = useState("");
  const [filterSpecialization, setFilterSpecialization] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [selectedTeacher, setSelectedTeacher] = useState<Teacher | null>(null);
  const [teacherRatings, setTeacherRatings] = useState<{ [key: number]: { average: number; count: number } }>({});

  const emptyForm = {
    display_name: "", phone: "", email: "", country_code: "",
    specialization: "", status: "active" as Teacher["status"],
    qualifications: "", years_of_experience: "", languages: "", bio: "",
  };
  const [form, setForm] = useState(emptyForm);

  // Stats
  const stats = useMemo(() => ({
    total: teachers.length,
    active: teachers.filter((t) => t.status === "active").length,
    inactive: teachers.filter((t) => t.status === "inactive").length,
  }), [teachers]);

  // Filtered teachers
  const filteredTeachers = useMemo(() => {
    let result = teachers;
    if (filterStatus) result = result.filter((t) => t.status === filterStatus);
    if (filterSpecialization) result = result.filter((t) => t.specialization === filterSpecialization);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter((t) =>
        t.full_name.toLowerCase().includes(q) ||
        t.teacher_code.toLowerCase().includes(q) ||
        t.email?.toLowerCase().includes(q) ||
        t.phone.includes(q)
      );
    }
    return result;
  }, [teachers, filterStatus, filterSpecialization, searchQuery]);

  // Specializations list
  const specializations = useMemo(() => {
    const specs = new Set(teachers.map((t) => t.specialization).filter(Boolean));
    return Array.from(specs) as string[];
  }, [teachers]);

  const loadTeachers = useCallback(() => {
    setLoading(true);
    getTeachers()
      .then((r) => setTeachers(r.data))
      .catch((err) => setError(err instanceof Error ? err.message : "تعذر تحميل البيانات"))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    loadTeachers();
    getPrograms().then((r) => setPrograms(r.data)).catch(() => {});
  }, [loadTeachers]);

  // Load ratings for teachers
  useEffect(() => {
    teachers.forEach((t) => {
      getTeacherRatings(t.id)
        .then((r) => {
          setTeacherRatings((prev) => ({
            ...prev,
            [t.id]: { average: r.average_rating, count: r.ratings_count },
          }));
        })
        .catch(() => {});
    });
  }, [teachers]);

  function openCreate() {
    setForm(emptyForm);
    setEditingId(null);
    setShowForm(true);
  }

  function openEdit(t: Teacher) {
    setForm({
      display_name: t.display_name,
      phone: t.phone,
      email: t.email ?? "",
      country_code: t.country_code ?? "",
      specialization: t.specialization ?? "",
      status: t.status,
      qualifications: t.qualifications ?? "",
      years_of_experience: t.years_of_experience?.toString() ?? "",
      languages: t.languages ?? "",
      bio: t.bio ?? "",
    });
    setEditingId(t.id);
    setShowForm(true);
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    try {
      const payload = {
        ...form,
        years_of_experience: form.years_of_experience ? Number(form.years_of_experience) : undefined,
      };
      if (editingId) {
        await updateTeacher(editingId, payload);
      } else {
        await createTeacher(payload);
      }
      setShowForm(false);
      loadTeachers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "فشل الحفظ");
    }
  }

  async function handleDelete(id: number) {
    if (!confirm("هل أنت متأكد من حذف هذا المعلم؟")) return;
    try {
      await deleteTeacher(id);
      loadTeachers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "فشل الحذف");
    }
  }

  async function toggleStatus(t: Teacher) {
    const newStatus = t.status === "active" ? "inactive" : "active";
    try {
      await updateTeacher(t.id, { status: newStatus });
      loadTeachers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "فشل تحديث الحالة");
    }
  }

  return (
    <div>
      {/* Header */}
      <div className="mb-6 flex items-center justify-between">
        <div>
          <h1 className="text-xl font-bold text-slate-800">المعلمون</h1>
          <p className="text-sm text-slate-500">إجمالي: {stats.total} معلم</p>
        </div>
        <button
          onClick={openCreate}
          className="rounded-lg bg-slate-800 px-4 py-2 text-sm font-medium text-white hover:bg-slate-700"
        >
          + معلم جديد
        </button>
      </div>

      {/* Stats */}
      <div className="mb-6 grid grid-cols-3 gap-3">
        <div className="rounded-xl bg-slate-800 p-4 text-center text-white">
          <p className="text-2xl font-bold">{stats.total}</p>
          <p className="text-xs">إجمالي</p>
        </div>
        <div className="rounded-xl bg-green-100 p-4 text-center">
          <p className="text-2xl font-bold text-green-800">{stats.active}</p>
          <p className="text-xs text-green-600">نشط</p>
        </div>
        <div className="rounded-xl bg-red-100 p-4 text-center">
          <p className="text-2xl font-bold text-red-800">{stats.inactive}</p>
          <p className="text-xs text-red-600">غير نشط</p>
        </div>
      </div>

      {/* Search & Filters */}
      <div className="mb-4 flex flex-wrap items-center gap-3">
        <div className="flex-1">
          <input
            placeholder="🔎 ابحث بالاسم / الهاتف / الكود / البريد..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full rounded-xl border border-slate-300 px-4 py-2.5 text-sm"
          />
        </div>
        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          className="rounded-xl border border-slate-300 px-3 py-2.5 text-sm"
        >
          <option value="">كل الحالات</option>
          <option value="active">نشط</option>
          <option value="inactive">غير نشط</option>
        </select>
        <select
          value={filterSpecialization}
          onChange={(e) => setFilterSpecialization(e.target.value)}
          className="rounded-xl border border-slate-300 px-3 py-2.5 text-sm"
        >
          <option value="">كل التخصصات</option>
          {specializations.map((s) => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>
      </div>

      {loading && <p className="text-sm text-slate-500">جارٍ التحميل...</p>}
      {error && <p className="mb-4 text-sm text-red-600">{error}</p>}

      {/* Teachers Table */}
      {!loading && !error && (
        <div className="overflow-x-auto rounded-xl border border-slate-200 bg-white">
          <table className="w-full text-sm">
            <thead className="border-b border-slate-200 bg-slate-50 text-slate-500">
              <tr>
                <th className="px-4 py-3 text-right">المعلم</th>
                <th className="px-4 py-3 text-right">التخصص</th>
                <th className="px-4 py-3 text-right">البرامج</th>
                <th className="px-4 py-3 text-right">الطلاب</th>
