                    onClick={() => setSelectedTeacher(t)}
                  >
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-3">
                        {t.avatar_url ? (
                          <img
                            src={t.avatar_url}
                            alt={t.full_name}
                            className="h-10 w-10 rounded-full object-cover"
