                        .map((p) => p.name)
                        .join(", ") || "—"}
                    </td>
                    <td className="px-4 py-3 text-slate-600">—</td>
                    <td className="px-4 py-3 text-slate-600">
                      {t.activeContract ? CONTRACT_LABEL[t.activeContract.contract_type] || t.activeContract.contract_type : "—"}
                    </td>
                    <td className="px-4 py-3">
                      {rating && rating.count > 0 ? (
                        <div className="flex items-center gap-1">
                          <span className="text-amber-500">★</span>
                          <span className="font-medium text-slate-800">{rating.average.toFixed(1)}</span>
                          <span className="text-xs text-slate-400">({rating.count})</span>
                        </div>
                      ) : (
                        <span className="text-slate-400">—</span>
                      )}
                    </td>
                    <td className="px-4 py-3">
                      <span className={`rounded-full px-2 py-1 text-xs ${STATUS_COLORS[t.status]}`}>
                        {STATUS_LABEL[t.status]}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex gap-1" onClick={(e) => e.stopPropagation()}>
                        <button
