                          className="rounded bg-blue-50 px-2 py-1 text-xs text-blue-600 hover:bg-blue-100"
                        >
                          تعديل
                        </button>
                        <button
                          onClick={() => toggleStatus(t)}
                          className="rounded bg-amber-50 px-2 py-1 text-xs text-amber-600 hover:bg-amber-100"
