                <div className="grid grid-cols-2 gap-3">
                  <input
                    placeholder="الاسم *"
                    value={form.display_name}
                    onChange={(e) => setForm({ ...form, display_name: e.target.value })}
                    className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
                    required
                  />
                  <input
                    placeholder="الهاتف *"
                    value={form.phone}
                    onChange={(e) => setForm({ ...form, phone: e.target.value })}
                    className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
                    required
                  />
                  <input
                    placeholder="البريد الإلكتروني"
                    value={form.email}
                    onChange={(e) => setForm({ ...form, email: e.target.value })}
                    className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
                  />
                  <input
                    placeholder="كود الدولة"
                    value={form.country_code}
                    onChange={(e) => setForm({ ...form, country_code: e.target.value })}
                    className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
                  />
                </div>
              </div>

              {/* Professional Info */}
              <div className="rounded-lg bg-blue-50 p-4 space-y-3">
                <h4 className="font-medium text-blue-700">💼 البيانات المهنية</h4>
                <div className="grid grid-cols-2 gap-3">
                  <input
                    placeholder="التخصص"
                    value={form.specialization}
                    onChange={(e) => setForm({ ...form, specialization: e.target.value })}
                    className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
                  />
                  <input
                    placeholder="المؤهلات"
                    value={form.qualifications}
                    onChange={(e) => setForm({ ...form, qualifications: e.target.value })}
                    className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
                  />
                  <input
                    placeholder="سنوات الخبرة"
                    type="number"
                    value={form.years_of_experience}
                    onChange={(e) => setForm({ ...form, years_of_experience: e.target.value })}
                    className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
                  />
                  <input
                    placeholder="اللغات"
                    value={form.languages}
                    onChange={(e) => setForm({ ...form, languages: e.target.value })}
                    className="rounded-lg border border-slate-300 px-3 py-2 text-sm"
