// Teacher Profile Drawer Component
function TeacherProfileDrawer({ teacher, onClose, onEdit }: {
  teacher: Teacher;
  onClose: () => void;
  onEdit: () => void;
}) {
  const [ratings, setRatings] = useState<TeacherRating[]>([]);
  const [averageRating, setAverageRating] = useState(0);
  const [ratingsCount, setRatingsCount] = useState(0);
  const [activeTab, setActiveTab] = useState("overview");

  useEffect(() => {
    getTeacherRatings(teacher.id)
      .then((r) => {
        setRatings(r.ratings);
        setAverageRating(r.average_rating);
        setRatingsCount(r.ratings_count);
      })
      .catch(() => {});
  }, [teacher.id]);

  return (
    <div className="fixed inset-0 z-50 flex">
      <div className="flex-1 bg-black/50" onClick={onClose} />
      <div className="flex h-full w-full max-w-2xl flex-col bg-white shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-slate-200 p-4">
          <div className="flex items-center gap-3">
            {teacher.avatar_url ? (
              <img
                src={teacher.avatar_url}
                alt={teacher.full_name}
                className="h-12 w-12 rounded-full object-cover"
              />
            ) : (
              <div className="flex h-12 w-12 items-center justify-center rounded-full bg-blue-100 text-xl font-bold text-blue-600">
                {teacher.full_name.charAt(0)}
              </div>
            )}
            <div>
              <h2 className="text-lg font-bold text-slate-800">{teacher.full_name}</h2>
              <p className="text-sm text-slate-500">{teacher.specialization ?? "معلم"}</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <span className={`rounded-full px-3 py-1 text-xs ${STATUS_COLORS[teacher.status]}`}>
              {STATUS_LABEL[teacher.status]}
            </span>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600">✕</button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-1 border-b border-slate-200 px-4">
          {[
            { key: "overview", label: "نظرة عامة" },
            { key: "students", label: "الطلاب" },
            { key: "schedule", label: "الجدول" },
            { key: "ratings", label: "التقييمات" },
          ].map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`rounded-t-lg px-4 py-2 text-sm ${
                activeTab === tab.key
                  ? "bg-slate-100 font-medium text-slate-800"
                  : "text-slate-500 hover:text-slate-700"
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4">
          {activeTab === "overview" && (
            <div className="space-y-4">
              {/* Stats */}
              <div className="grid grid-cols-2 gap-3">
                <div className="rounded-xl bg-blue-50 p-3 text-center">
                  <p className="text-xs text-blue-600">الطلاب النشطين</p>
                  <p className="text-lg font-bold text-blue-800">—</p>
                </div>
                <div className="rounded-xl bg-green-50 p-3 text-center">
                  <p className="text-xs text-green-600">حصص الشهر</p>
                  <p className="text-lg font-bold text-green-800">—</p>
                </div>
                <div className="rounded-xl bg-purple-50 p-3 text-center">
                  <p className="text-xs text-purple-600">المستحق</p>
                  <p className="text-lg font-bold text-purple-800">—</p>
                </div>
                <div className="rounded-xl bg-amber-50 p-3 text-center">
                  <p className="text-xs text-amber-600">التقييم</p>
                  <p className="text-lg font-bold text-amber-800">
                    {averageRating > 0 ? `${averageRating.toFixed(1)}/5` : "—"}
                  </p>
                </div>
              </div>

              {/* Professional Info */}
              <div className="rounded-xl border border-slate-200 p-4">
                <h3 className="mb-3 text-sm font-semibold text-slate-800">💼 البيانات المهنية</h3>
                <div className="space-y-2 text-sm text-slate-600">
                  <p><strong>التخصص:</strong> {teacher.specialization ?? "—"}</p>
                  <p><strong>المؤهلات:</strong> {teacher.qualifications ?? "—"}</p>
                  <p><strong>سنوات الخبرة:</strong> {teacher.years_of_experience ?? "—"}</p>
                  <p><strong>اللغات:</strong> {teacher.languages ?? "—"}</p>
                  <p><strong>التعاقد:</strong> {teacher.activeContract ? CONTRACT_LABEL[teacher.activeContract.contract_type] : "—"}</p>
                  <p><strong>تاريخ الانضمام:</strong> {teacher.joined_at ?? "—"}</p>
                </div>
              </div>

              {/* Bio */}
              {teacher.bio && (
                <div className="rounded-xl border border-slate-200 p-4">
                  <h3 className="mb-2 text-sm font-semibold text-slate-800">📝 نبذة تعريفية</h3>
                  <p className="text-sm text-slate-600">{teacher.bio}</p>
                </div>
              )}
            </div>
          )}

          {activeTab === "students" && (
            <div className="rounded-xl border border-slate-200 p-4">
              <p className="text-sm text-slate-400">لا يوجد طلاب مرتبطين بعد</p>
            </div>
          )}

          {activeTab === "schedule" && (
            <div className="rounded-xl border border-slate-200 p-4">
              <p className="text-sm text-slate-400">لا توجد حصص مجدولة</p>
            </div>
          )}

          {activeTab === "ratings" && (
            <div className="space-y-3">
              {ratings.length === 0 ? (
                <p className="text-sm text-slate-400">لا توجد تقييمات بعد</p>
              ) : (
                ratings.map((r) => (
                  <div key={r.id} className="rounded-xl border border-slate-200 p-3">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span className="text-amber-500">{"★".repeat(r.rating)}</span>
                        <span className="text-sm text-slate-600">
                          {r.student?.full_name ?? r.parent?.name ?? "مجهول"}
                        </span>
                      </div>
                      <span className="text-xs text-slate-400">
                        {new Date(r.created_at).toLocaleDateString("ar-EG")}
                      </span>
                    </div>
                    {r.comment && (
                      <p className="mt-2 text-sm text-slate-600">{r.comment}</p>
                    )}
                  </div>
                ))
              )}
            </div>
          )}
        </div>

        {/* Actions */}
        <div className="flex gap-2 border-t border-slate-200 p-4">
          <button
            onClick={onEdit}
            className="flex-1 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
          >
            ✏️ تعديل
          </button>
          <button
            onClick={() => {
              const newStatus = teacher.status === "active" ? "inactive" : "active";
              updateTeacher(teacher.id, { status: newStatus }).then(() => {
                onClose();
              });
            }}
            className="flex-1 rounded-lg bg-amber-50 px-4 py-2 text-sm font-medium text-amber-600 hover:bg-amber-100"
          >
            {teacher.status === "active" ? "⏸ إيقاف" : "▶ تفعيل"}
          </button>
        </div>
      </div>
    </div>
  );
}

