input.newString:
public function schedule(Request $request, Teacher $teacher)
    {
        return response()->json($teacher->lessons()->with(['student', 'program', 'level'])->orderBy('scheduled_start_at', 'desc')->paginate(50));
    }

    public function students(Request $request, Teacher $teacher)
    {
        // Get students through subscriptions
        $students = \App\Models\Student::whereHas('subscriptions', function ($q) use ($teacher) {
            $q->where('teacher_id', $teacher->id);
        })->with(['subscriptions' => function ($q) use ($teacher) {
            $q->where('teacher_id', $teacher->id);
        }])->get();

        return response()->json([
            'students' => $students,
            'total' => $students->count(),
        ]);
    }

    public function lessonsSummary(Request $request, Teacher $teacher)
    {
        $now = now();
        $startOfMonth = $now->copy()->startOfMonth();
        $endOfMonth = $now->copy()->endOfMonth();

        $lessons = $teacher->lessons();

        $total = $lessons->count();
        $completed = $lessons->where('status', 'completed')->count();
        $upcoming = $lessons->where('scheduled_start_at', '>', $now)->count();
        $cancelled = $lessons->where('status', 'cancelled')->count();

        $thisMonth = $lessons->whereBetween('scheduled_start_at', [$startOfMonth, $endOfMonth])->count();
        $thisMonthCompleted = $lessons->whereBetween('scheduled_start_at', [$startOfMonth, $endOfMonth])->where('status', 'completed')->count();

        // Recent lessons (last 5 completed)
        $recentLessons = $teacher->lessons()
            ->with(['student', 'program', 'level'])
            ->where('status', 'completed')
            ->orderBy('scheduled_start_at', 'desc')
            ->limit(5)
            ->get();

        // Upcoming lessons (next 5)
        $upcomingLessons = $teacher->lessons()
            ->with(['student', 'program', 'level'])
            ->where('scheduled_start_at', '>', $now)
            ->orderBy('scheduled_start_at', 'asc')
            ->limit(5)
            ->get();

        return response()->json([
            'summary' => [
                'total' => $total,
                'completed' => $completed,
                'upcoming' => $upcoming,
                'cancelled' => $cancelled,
                'this_month' => $thisMonth,
                'this_month_completed' => $thisMonthCompleted,
            ],
            'recent_lessons' => $recentLessons,
            'upcoming_lessons' => $upcomingLessons,
        ]);
    }

